from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda u: u.IncludeWeeklys()
                        .Strikes(-100, 100)
                        .Expiration(timedelta(0), timedelta(days=365))
        )
        self.option_canonical = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.bucket_end = None
        self.bucket_open = None
        self.bucket_high = None
        self.bucket_low = None
        self.bucket_close = None
        self.bucket_volume = 0
        self.bucket_count = 0

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.no_replacement_date = None

    def OnData(self, slice: Slice):
        now = self.Time
        today = now.date()

        self._handle_expiration_processing(slice)
        self._handle_equity_assignment()

        self._evaluate_profit_target(slice)
        self._evaluate_time_stop()

        bar = slice.Bars.get(self.spy_symbol)
        if bar is None:
            return

        if not self._is_regular_session(bar.EndTime):
            return

        crossover = self._update_five_minute_bar(bar)

        if not crossover:
            return

        if self.held_symbol is not None or self._entry_is_open():
            return

        if self.no_replacement_date == today:
            return

        if not (time(9, 45) <= bar.EndTime.time() <= time(14, 30)):
            return

        self._try_enter(slice, bar.Close)

    def _update_five_minute_bar(self, minute_bar):
        end = minute_bar.EndTime.replace(second=0, microsecond=0)

        if self.bucket_end is None or end.minute % 5 != 0:
            if self.bucket_end is None:
                self.bucket_end = end.replace(
                    minute=(end.minute // 5) * 5 + 5
                )

            if end >= self.bucket_end:
                crossover = False

                if self.bucket_count == 5:
                    previous_fast = self.fast.Current.Value
                    previous_slow = self.slow.Current.Value

                    self.fast.Update(self.bucket_end, self.bucket_close)
                    self.slow.Update(self.bucket_end, self.bucket_close)

                    crossover = (
                        self.fast.IsReady and
                        self.slow.IsReady and
                        previous_fast <= previous_slow and
                        self.fast.Current.Value > self.slow.Current.Value
                    )

                self.bucket_end = end.replace(
                    minute=(end.minute // 5) * 5 + 5
                )
                self.bucket_open = None
                self.bucket_high = None
                self.bucket_low = None
                self.bucket_close = None
                self.bucket_volume = 0
                self.bucket_count = 0
            else:
                crossover = False

        if self.bucket_open is None:
            self.bucket_open = minute_bar.Open
            self.bucket_high = minute_bar.High
            self.bucket_low = minute_bar.Low
        else:
            self.bucket_high = max(self.bucket_high, minute_bar.High)
            self.bucket_low = min(self.bucket_low, minute_bar.Low)

        self.bucket_close = minute_bar.Close
        self.bucket_volume += minute_bar.Volume
        self.bucket_count += 1

        return crossover

    def _try_enter(self, slice, spy_price):
        chain = slice.OptionChains.get(self.option_canonical)
        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        algorithm_date = self.Time.date()
        expirations = sorted({
            c.Expiry.date() for c in chain
            if c.Right == OptionRight.Call and
            (c.Expiry.date() - algorithm_date).days >= 7
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least seven days away.")
            return

        expiry_date = expirations[0]
        candidates = [
            c for c in chain
            if c.Right == OptionRight.Call and
            c.Expiry.date() == expiry_date and
            c.Strike >= 1.01 * spy_price
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = sorted(
            candidates,
            key=lambda c: (c.Strike, str(c.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Entry submitted: {}".format(selected.Symbol))

    def _evaluate_profit_target(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        security = self.Securities.get(self.held_symbol)
        if security is None:
            return

        bid = security.BidPrice
        ask = security.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._cancel_exit_order()
            self.exit_ticket = self.MarketOrder(
                self.held_symbol,
                -self.Portfolio[self.held_symbol].Quantity
            )
            self.Debug("Profit target exit submitted: {}".format(
                self.held_symbol
            ))

    def _evaluate_time_stop(self):
        if self.held_symbol is None:
            return

        expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        previous_trading_day = self._previous_trading_day(expiry)

        if (
            self.Time.date() == previous_trading_day and
            self.Time.time() >= time(15, 45)
        ):
            self._cancel_exit_order()
            self.exit_ticket = self.MarketOrder(
                self.held_symbol,
                -self.Portfolio[self.held_symbol].Quantity
            )
            self.Debug("Expiration time-stop submitted: {}".format(
                self.held_symbol
            ))

    def _handle_expiration_processing(self, slice):
        if self.held_symbol is None:
            return

        expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        if self.Time.date() >= expiry:
            self.no_replacement_date = self.Time.date()
            self._cancel_exit_order()
            quantity = self.Portfolio[self.held_symbol].Quantity
            if quantity != 0:
                self.exit_ticket = self.MarketOrder(
                    self.held_symbol, -quantity
                )
                self.Debug("Unexpected expiration holding liquidated.")

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status != OrderStatus.Filled:
            return

        if self.entry_ticket and order_event.OrderId == self.entry_ticket.OrderId:
            self.held_symbol = order_event.Symbol
            self.entry_price = order_event.FillPrice
            self.entry_ticket = None
            self.Debug("Entry filled: {} at {}".format(
                self.held_symbol, self.entry_price
            ))

        elif self.exit_ticket and order_event.OrderId == self.exit_ticket.OrderId:
            self.Debug("Exit filled: {} at {}".format(
                order_event.Symbol, order_event.FillPrice
            ))
            self.exit_ticket = None
            if self.Portfolio[order_event.Symbol].Quantity == 0:
                self.held_symbol = None
                self.entry_price = None

        self._handle_equity_assignment()

    def OnAssignmentOrderEvent(self, assignment_event):
        self.no_replacement_date = self.Time.date()
        self.Debug("Unexpected option assignment/exercise handled.")
        self._handle_equity_assignment()

    def _handle_equity_assignment(self):
        quantity = self.Portfolio[self.spy_symbol].Quantity
        if quantity != 0:
            self.MarketOrder(self.spy_symbol, -quantity)
            self.no_replacement_date = self.Time.date()
            self.Debug("Unexpected SPY assignment position liquidated.")

    def _entry_is_open(self):
        return (
            self.entry_ticket is not None and
            self.entry_ticket.Status not in
            [OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid]
        )

    def _cancel_exit_order(self):
        if self.exit_ticket is not None:
            if self.exit_ticket.Status not in [
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                self.exit_ticket.Cancel("Replacing exit order")
            self.exit_ticket = None

    def _previous_trading_day(self, date):
        candidate = date - timedelta(days=1)
        while not self.Securities[self.spy_symbol].Exchange.Hours.IsDateOpen(
            candidate
        ):
            candidate -= timedelta(days=1)
        return candidate

    def _is_regular_session(self, end_time):
        t = end_time.time()
        return time(9, 31) <= t <= time(16, 0)

