            self.blocked_entry_date = self.Time.date()

    def HasOptionPosition(self):
        return (
            self.entry_symbol is not None
            and self.Portfolio[self.entry_symbol].Invested
        )

    def EntryOrderOpen(self):
        return (
            self.entry_ticket is not None
            and self.entry_ticket.Status in [
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            ]
        )

    def CancelOpenExit(self):
        if self.exit_ticket is not None and self.exit_ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]:
            self.exit_ticket.Cancel("Replacing exit order")

    def IsTradingDayBeforeExpiry(self, current_date: date, expiry_date: date):
        next_trading_day = current_date + timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            next_trading_day
        ):
            next_trading_day += timedelta(days=1)

        return next_trading_day == expiry_date

    def OnSecuritiesChanged(self, changes: SecurityChanges):
        consolidator = TradeBarConsolidator(timedelta(minutes=1))
        consolidator.DataConsolidated += self.OnDataConsolidated
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)
