from collections import deque


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(timedelta(days=0), timedelta(days=365))
        )
        self.option_symbol = self.option.Symbol

        self.fast_period = 5
        self.slow_period = 20
        self.closes = deque(maxlen=self.slow_period)

        self.previous_fast = None
        self.previous_slow = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_contract = None
        self.entry_price = None
        self.no_entry_date = None

        self.current_bucket = None
        self.bucket_bars = []

    def OnData(self, slice: Slice):
        now = self.Time
        today = now.date()

        # Immediately liquidate unexpected SPY equity positions, including
        # positions caused by exercise or assignment.
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            self.Debug(
                f"Unexpected exercise/assignment handling: liquidating "
                f"{spy_quantity} SPY shares at {now}"
            )
            self.MarketOrder(self.spy, -spy_quantity)

        self._process_expiration_safety(slice, now)

        if self.held_contract is not None:
            self._process_held_option_exit(slice, now)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            return

        completed_bar = self._update_five_minute_bar(spy_bar)
        if completed_bar is None:
            return

        self._evaluate_crossover(completed_bar, slice, today)

    def _update_five_minute_bar(self, minute_bar: TradeBar):
        local_time = self._to_new_york(minute_bar.EndTime)
        local_date = local_time.date()

        # Regular-session bars are aligned so 09:31 through 09:35 ends at 09:35.
        minute = local_time.hour * 60 + local_time.minute
        if minute < 9 * 60 + 31 or minute > 16 * 60:
            return None

        bucket_end_minute = ((minute - (9 * 60 + 30)) // 5) * 5 + (9 * 60 + 30)
        bucket_end = datetime.combine(
            local_date,
            time(bucket_end_minute // 60, bucket_end_minute % 60)
        )
        bucket_key = bucket_end

        if self.current_bucket is None:
            self.current_bucket = bucket_key

        completed = None

        if bucket_key != self.current_bucket:
            if len(self.bucket_bars) == 5:
                completed = self._make_consolidated_bar(
                    self.current_bucket,
                    self.bucket_bars
                )

            self.current_bucket = bucket_key
            self.bucket_bars = []

        # Only actual minute bars are counted. Missing minutes invalidate
        # that five-minute interval rather than causing synthetic data.
        if local_date == self.current_bucket.date():
            self.bucket_bars.append(minute_bar)

        return completed

    def _make_consolidated_bar(self, bucket_end_local, bars):
        if len(bars) != 5:
            return None

        bars = sorted(bars, key=lambda bar: bar.EndTime)

        return TradeBar(
            self.spy,
            bucket_end_local - timedelta(minutes=5),
            bucket_end_local,
            bars[0].Open,
            max(bar.High for bar in bars),
            min(bar.Low for bar in bars),
            bars[-1].Close,
            sum(bar.Volume for bar in bars)
        )

    def _evaluate_crossover(self, bar: TradeBar, slice: Slice, today):
        self.closes.append(float(bar.Close))

        if len(self.closes) < self.slow_period:
            return

        fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
        slow = sum(self.closes) / self.slow_period

        bullish_cross = (
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        bar_time = self._to_new_york(bar.EndTime).time()
        if not (time(9, 45) <= bar_time <= time(14, 30)):
            return

        if not bullish_cross:
            return

        if self.no_entry_date == today:
            return

        if self.held_contract is not None or self._entry_order_is_open():
            return

        self._try_enter(slice, today)

    def _try_enter(self, slice: Slice, algorithm_date):
        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug(f"Skipped selection on {algorithm_date}: no option chain")
            return

        minimum_expiry = algorithm_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug(
                f"Skipped selection on {algorithm_date}: "
                f"no expiration at least seven calendar days away"
            )
            return

        selected_expiry = expirations[0]
        spy_price = float(self.Securities[self.spy].Price)
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"Skipped selection on {algorithm_date}: "
                f"no qualifying call at expiration {selected_expiry}"
            )
            return

        candidates.sort(key=lambda contract: (
            contract.Strike,
            str(contract.Symbol)
        ))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol} "
